    foreach($g in $segments){$w=@($samples|Where-Object {$_.ms-ge$g.ms-and$_.ms-lt$g.ms+1100-and[double]$_.combatWeight-gt.5-and[double]$_.speed-gt.3});$row.moving+=[ordered]@{attack=$g.moveattack;travellingAttackSamples=$w.Count}
     if(!$w.Count){throw "Attack while $($g.moveattack) not presented while travelling"}}
    $row.checks.Add('Light attacks presented while walking forward, right, back and running, with the partner still travelling')}
   if($case-eq'airattack'){$row.airAttacks=@()
    foreach($g in $segments){$w=@($samples|Where-Object {$_.ms-ge$g.ms-and$_.ms-lt$g.ms+1500-and[double]$_.combatWeight-gt.5-and[double]$_.airWeight-gt.5});$row.airAttacks+=[ordered]@{jump=$g.air;combatInAir=$w.Count}
     if(!$w.Count){throw "Jump attack ($($g.air)) not presented in the air"}}
    if(@($samples|Where-Object {$_.ms-ge$caseMs-900-and[double]$_.combatWeight-gt.05}).Count){throw 'Partner did not settle after the jump attacks'}
    $row.checks.Add('Early, late and running jump attacks presented combat in the air, then settled')}
   if($case-eq'arcs'){$row.arcs=@()
    foreach($g in $segments){$mv2=@($samples|Where-Object {$_.ms-ge$g.ms+300-and$_.ms-lt$g.ms+$g.durationMs-and[double]$_.speed-gt.5})
     $gaitOk=switch($g.arc){'walk'{@($mv2|Where-Object {[double]$_.runMix-lt.5}).Count};'run'{@($mv2|Where-Object {[double]$_.runMix-gt.5-and[double]$_.sprintMix-lt.5}).Count};'sprint'{@($mv2|Where-Object {[double]$_.sprintMix-gt.5}).Count}}
     $inPlace=@($mv2|Where-Object {[double]$_.turnWeight-gt.5}).Count;$row.arcs+=[ordered]@{arc=$g.arc;moving=$mv2.Count;gait=$gaitOk;inPlaceTurn=$inPlace}
     if($mv2.Count-lt4-or$gaitOk-lt3){throw "Arc $($g.arc): moving $($mv2.Count), in gait $gaitOk"};if($inPlace){throw "Arc $($g.arc) presented an in-place turn while travelling"}}
    $row.checks.Add('Walk, run and sprint arcs presented in their gaits while turning, without in-place turn clips')}
   if($case-eq'slideexit'){$sl=@($samples|Where-Object {[double]$_.slideWeight-gt.8});$first=@($sl|Where-Object {$_.ms-lt5200}).Count;$second=@($sl|Where-Object {$_.ms-ge5200}).Count;$row.slideSamples=@($first,$second)
    if(!$first-or!$second){throw "Slides presented $first and $second"};$jt=@($segments|Where-Object {$_.takeoff})[0];if(!@($row.air|Where-Object {$_.from-ge$jt.ms-and$_.from-lt$jt.ms+1000}).Count){throw 'No air episode after the slide jump'}
    $end=@($samples|Where-Object {$_.ms-ge11000});if(@($end|Where-Object {[double]$_.stanceMix-gt.2}).Count){throw 'Did not stand after the second slide'};$row.checks.Add('Both slides presented, jump out of the slide airborne, stand exit settled standing')}
   if($case-eq'stairs'){C $peer 'coop_observer_camera off'
    $up=@($samples|Where-Object {[double]$_.terrainWeight-gt.5-and[double]$_.terrainGrade-gt.05}).Count;$dn=@($samples|Where-Object {[double]$_.terrainWeight-gt.5-and[double]$_.terrainGrade-lt-.05}).Count;$row.stairsUp=$up;$row.stairsDown=$dn
    if(!$up-or!$dn){throw "Stair gait not presented (up $up, down $dn)"};$row.checks.Add("Partner stair gait up ($up samples) and down ($dn samples)")}
   if($case-in'runjump','arcs','slideexit','moveattack','airattack'){C $peer 'coop_observer_camera off'}
   if($case-eq'mana'){C $peer 'coop_observer_camera off'
    $drink=@($samples|Where-Object {$_.useVariant-eq1-and[double]$_.useWeight-gt.5});$row.drinkSamples=$drink.Count
    if(!($row.manaBefore-ge1-and$row.manaAfter-lt$row.manaBefore)){throw "Mana potion not consumed ($($row.manaBefore) -> $($row.manaAfter))"};$row.checks.Add("Mana potion consumed ($($row.manaBefore) -> $($row.manaAfter))")
    if(!$drink.Count){throw 'Partner drink reach not presented'};$row.checks.Add("Partner drink reach presented in $($drink.Count) samples")}
   if($case-eq'note'){C $peer 'coop_observer_camera off'
    $read=@($samples|Where-Object {$_.readingHold-and$_.useVariant-eq6-and[double]$_.useWeight-gt.5});$row.readingSamples=$read.Count
    $row.sourceLogics=@($samples|ForEach-Object {$_.sourceLogic}|Sort-Object -Unique)
    if(!@($samples|Where-Object {$_.sourceLogic-eq4}).Count){throw 'Source never entered the native reading UI (ReadNote4)'}
    if(!$read.Count){throw 'Partner reading hold not presented'};$row.checks.Add("Partner reading hold presented in $($read.Count) samples")}
   if($case-eq'crouchheavy'){C $peer 'coop_observer_camera off'
    $heavy=@($samples|Where-Object {$_.combatVariant-eq18-and[double]$_.combatWeight-gt.5});$row.heavySamples=$heavy.Count
    $row.combatVariants=@($samples|ForEach-Object {$_.combatVariant}|Sort-Object -Unique)
    if(!$heavy.Count){throw 'Partner crouched heavy (combat variant 18) not presented'};$row.checks.Add("Partner crouched heavy presented in $($heavy.Count) samples")}
   if($case-eq'kick'){C $peer 'coop_observer_camera off'
    $kicks=@($samples|Where-Object {$_.combatVariant-eq17-and[double]$_.combatWeight-gt.5});$row.kickSamples=$kicks.Count
    if(!$kicks.Count){throw 'Partner kick (combat variant 17) not presented'};$row.checks.Add("Partner kick presented in $($kicks.Count) samples")}
   if($case-eq'fall'){$zs=@($samples|Where-Object {$_.position}|ForEach-Object {[double]$_.position[2]});$row.fallMetres=[Math]::Round((($zs|Measure-Object -Maximum).Maximum)-$zs[-1],2)
    if($row.fallMetres-lt3){throw "Source fell only $($row.fallMetres) m"};$row.checks.Add("Source fell $($row.fallMetres) m")}
   $row.passed=$true
  }catch{$row.failure=$_.Exception.Message}
  foreach($c in $capture,$peerCapture){if($c){try{if(!$c.HasExited){Stop-Process -Id $c.Id}}catch{}}}
  try{try{Restore $key}catch{$row.restoreRetried=$_.Exception.Message;Start-Sleep -Milliseconds 1500;Restore "$key-retry"};$row.restored=$true}catch{$row.restored=$false;$row.failure=(("$($row.failure); restore: "+$_.Exception.Message)).TrimStart('; ')}
  $rows.Add([pscustomobject]$row);Save "$out/$key.json" ([pscustomobject]$row)
  if(!$row.restored){throw "Fixture restore failed after $key"}
 }}
 $dirty=$false
}catch{$failure=$_.Exception.Message;Save "$out/failure.json" @{message=$failure;stack=$_.ScriptStackTrace}}finally{
 if($owned){
  if($dirty){try{Restore 'final'}catch{$failure=($failure+'; restore: '+$_.Exception.Message).TrimStart('; ')}}else{Disarm}
  $errors=[Collections.Generic.List[string]]::new()
  try{foreach($f in(Get-Content "$root/work/movement-integration/protected-save-hashes-before-v4.json" -Raw|ConvertFrom-Json)){if((Get-FileHash $f.Path).Hash-ne$f.Hash){$errors.Add('Protected file changed')}}}catch{$errors.Add($_.Exception.Message)}
  foreach($r in 'host','client'){try{$s=S $r;if($s.localGameLogicState-ne1-or!$s.remoteFresh-or(Q $r '--health' 1).current-ne56){$errors.Add("$r gameplay/transport/health not restored")}}catch{$errors.Add("$r status unavailable")}}
  if(Test-Path -LiteralPath $out){
   Save "$out/restoration.json" @{passed=(!$errors.Count);errors=@($errors)}
   $bad=@($rows|Where-Object {!$_.passed});if(!$failure-and$bad.Count){$failure="$($bad.Count) case(s) failed: "+(($bad|ForEach-Object {"$($_.source)-$($_.case): $($_.failure)"})-join ' | ')}
   if($errors.Count-and!$failure){$failure=$errors-join '; '}
   Save "$out/result.json" ([ordered]@{passed=(!$failure);failure=$failure;cases=@($rows);scope='Combat coverage without an opponent (1324, #11): light, combo, heavy, crouched light and heavy attacks; standing, crouched and airborne block; attacks while walking forward, right, back and running; early, late and running jump attacks. Traversal base (1321, #11): armed, crouched and holstered standing jumps, running and sprint jumps with moving landings, a 6 m fall, slides with crouched, jump and stand exits; both source roles, product controller, free camera; checked from the partner presentation state; fixture restored after every case.'})
  }
  [ordered]@{pid=$PID;operation='Coverage1267';take=$Take;ended=(Get-Date).ToString('o');state='finished'}|ConvertTo-Json|Set-Content "$root/work/movement-integration/native-operation-owner.json"
  $mutex.ReleaseMutex()
 };$mutex.Dispose()
}
if($failure){throw $failure};"PASS_COVERAGE $($rows.Count) cases"
